import unittest

from solucao import saudacao


class TestDevolverEmVezDeMostrar(unittest.TestCase):
    def test_devolve_ana(self):
        """a caixa devolve oi, Ana quando recebe Ana"""
        self.assertEqual(saudacao("Ana"), "oi, Ana")

    def test_devolve_bia(self):
        """a caixa devolve oi, Bia quando recebe Bia"""
        self.assertEqual(saudacao("Bia"), "oi, Bia")
